/* Generated by tools/convert.js from frontend/visitor/Pages.html — edit the source, not this file. */
/* HAMDI ITALIE — visitor content pages. All data is escaped with esc(). */

/** Plain text (admin-entered) → safe HTML paragraphs. */
function textBlock(s) {
  return String(s || '').trim().split(/\n{2,}/).map(function (p) {
    return '<p dir="auto">' + linkify(esc(p)).replace(/\n/g, '<br>') + '</p>';
  }).join('');
}

/** Turns https:// URLs in already-escaped text into safe links (new tab, no referrer leak). */
function linkify(escaped) {
  return escaped.replace(/https:\/\/[^\s<"']+/g, function (url) {
    var trail = (url.match(/[).,;:!?]+$/) || [''])[0];
    url = url.slice(0, url.length - trail.length);
    return '<a href="' + url + '" target="_blank" rel="noopener noreferrer" dir="ltr">' + url + '</a>' + trail;
  });
}

/** First https:// link in a text (e.g. a PayPal.me link), or ''. Bare "paypal.me/name" is accepted too. */
function firstLink(text) {
  text = String(text || '');
  var m = text.match(/https:\/\/[^\s<"']+/);
  if (m) return m[0].replace(/[).,;:!?]+$/, '');
  var p = text.match(/\b(?:www\.)?paypal\.me\/[A-Za-z0-9_.-]+/i);
  return p ? 'https://' + p[0].replace(/^www\./i, '').replace(/[.]+$/, '') : '';
}

/** A payment method's link, searched in the current language first, then in every language. */
function methodLink(m) {
  var link = firstLink(tf(m, 'instructions'));
  for (var i = 0; !link && i < SUPPORTED_LANGS.length; i++) link = firstLink(m['instructions_' + SUPPORTED_LANGS[i]]);
  return link;
}

function methodIcon(m) { return m.cash ? 'cash' : 'globe'; }

/**
 * A method's instructions with its payment link turned into a big button:
 * the URL in the text is replaced by the method name, and the button
 * (labelled with the method name) is shown below.
 */
function methodInstructions(m, buttonLabel) {
  var text = tf(m, 'instructions'), link = methodLink(m), name = tf(m, 'name');
  if (!text && !link) return '';
  var shown = text;
  if (link) {
    // Hide the raw address in the text (with or without https:// / www.) — the button carries it.
    var bare = link.replace(/^https:\/\//, '');
    shown = shown.split(link).join(name).split('www.' + bare).join(name).split(bare).join(name);
  }
  return (shown ? '<div class="small">' + textBlock(shown) + '</div>' : '') + (link ? payButton(link, buttonLabel || name) : '');
}

function payButton(href, label) {
  return '<a class="btn btn-pay btn-block" href="' + esc(safeUrl(href)) + '" target="_blank" rel="noopener noreferrer">' + icon('globe') + esc(label) + '</a>';
}

function setMain(html) { $('#main').innerHTML = html; window.scrollTo(0, 0); }

function pageSection(inner) { return '<section class="section"><div class="container stack-lg">' + inner + '</div></section>'; }

function loadingPage() { setMain(pageSection('<div class="grid grid-auto">' + skeletonCards(6, 90) + '</div>')); }

function errorPage(err, retry) {
  var notFound = /NOT_FOUND/.test((err && err.message) || '');
  setMain(pageSection('<div class="card stack"><div class="notice warning">' + icon('alert') + '<span>' +
    esc(notFound ? t('search.none') : t('common.error')) + '</span></div><div class="row">' +
    (retry && !notFound ? '<button class="btn btn-primary" id="retry">' + esc(t('common.retry')) + '</button>' : '') +
    '<a class="btn" href="#/">' + esc(t('nav.home')) + '</a></div></div>'));
  if (retry && $('#retry')) $('#retry').onclick = retry;
}

/** Runs an API call with skeleton + error handling, caching results per session. */
var PAGE_CACHE = {};
function loadData(key, call, render) {
  if (PAGE_CACHE[key]) { render(PAGE_CACHE[key]); return; }
  loadingPage();
  var token = key; currentLoad = token;
  call().then(function (d) {
    PAGE_CACHE[key] = d;
    if (currentLoad === token) render(d);
  }).catch(function (e) { if (currentLoad === token) errorPage(e, function () { loadData(key, call, render); }); });
}
var currentLoad = null;

function crumbs(items) {
  return '<nav class="crumbs" aria-label="breadcrumb"><a href="#/">' + esc(t('nav.home')) + '</a>' + items.map(function (i) {
    return '<span aria-hidden="true">' + icon('chevron', 'flip-rtl') + '</span>' + (i.href ? '<a href="' + i.href + '">' + esc(i.label) + '</a>' : '<span>' + esc(i.label) + '</span>');
  }).join('') + '</nav>';
}

function serviceList(services) {
  if (!services.length) return '<p class="muted">' + esc(t('svc.none')) + '</p>';
  return '<div class="svc-list">' + services.map(function (s) {
    return '<a class="card card-sm interactive svc-item" href="#/service/' + encodeURIComponent(s.slug) + '">' +
      '<span>' + esc(tf(s, 'title')) + '</span>' + icon('chevron', 'flip-rtl') + '</a>';
  }).join('') + '</div>';
}

function docList(docs) {
  return '<div class="grid grid-auto">' + docs.map(function (doc) {
    return '<div class="card card-sm doc-card"><span class="icon-badge">' + icon('file') + '</span>' +
      '<div class="doc-meta"><strong>' + esc(tf(doc, 'title') || doc.id) + '</strong><span class="muted small">' + esc((doc.mime || '').split('/').pop().toUpperCase()) + '</span></div>' +
      '<a class="btn btn-icon" href="' + esc(safeUrl(doc.url)) + '" target="_blank" rel="noopener" aria-label="' + esc(t('docs.download')) + '">' + icon('download') + '</a></div>';
  }).join('') + '</div>';
}

function faqList(faqs) {
  return '<div class="faq">' + faqs.map(function (f) {
    return '<details><summary>' + esc(tf(f, 'question')) + '</summary>' + textBlock(tf(f, 'answer')) + '</details>';
  }).join('') + '</div>';
}

/* ---- Services index ---------------------------------------------------------- */
function renderServicesIndex() {
  loadData('catalog', function () { return api('api_getCatalog'); }, function (d) {
    setMain(pageSection(crumbs([{ label: t('nav.services') }]) +
      '<div><h1>' + esc(t('svc.indexTitle')) + '</h1><p class="muted">' + esc(t('svc.indexSub')) + '</p></div>' +
      d.categories.map(function (c) {
        return '<details class="card cat-group"' + (d.categories.length < 4 ? ' open' : '') + '><summary>' +
          '<span class="icon-badge">' + icon(c.icon) + '</span><span class="cat-group-title"><strong>' + esc(tf(c, 'title')) + '</strong>' +
          '<span class="muted small">' + esc(tv('svc.count', { n: c.services.length })) + '</span></span>' + icon('chevron', 'chev') + '</summary>' +
          serviceList(c.services) +
          '<a class="link-more" href="#/category/' + encodeURIComponent(c.slug) + '">' + esc(t('cats.view')) + icon('arrow', 'flip-rtl') + '</a></details>';
      }).join('')));
  });
}

/* ---- Category ------------------------------------------------------------------- */
function renderCategory(slug) {
  loadData('cat:' + slug, function () { return api('api_getCategory', slug); }, function (d) {
    var c = d.category;
    setMain(pageSection(crumbs([{ label: t('nav.services'), href: '#/services' }, { label: tf(c, 'title') }]) +
      (c.image_url ? '<div class="media cat-hero"><img src="' + esc(safeUrl(c.image_url)) + '" alt="' + esc(tf(c, 'title')) + '"></div>' : '') +
      '<div class="page-head"><span class="icon-badge lg">' + icon(c.icon) + '</span><div><h1>' + esc(tf(c, 'title')) + '</h1>' +
      '<p class="muted">' + esc(tf(c, 'description')) + '</p></div></div>' +
      (c.slug === 'nuovi-immigrati' ? '<a class="card guide-cta" href="#/guide">' + icon('route') + '<strong>' + esc(t('guide.cta')) + '</strong>' + icon('arrow', 'flip-rtl') + '</a>' : '') +
      '<div><h2>' + esc(t('cat.services')) + '</h2>' + serviceList(d.services) + '</div>' +
      (d.documents.length ? '<div><h2>' + esc(t('cat.docs')) + '</h2>' + docList(d.documents) + '</div>' : '') +
      (d.faqs.length ? '<div><h2>' + esc(t('cat.faq')) + '</h2>' + faqList(d.faqs) + '</div>' : '')));
  });
}

/* ---- Service -------------------------------------------------------------------- */
function priceBox(price, methods, service) {
  var rows = '';
  var hasFee = price.amount_due > 0 || price.hamdi_fee > 0;
  if (hasFee) {
    rows += priceRow(t('price.hamdi'), price.hamdi_fee, price.currency);
    if (price.discount > 0) rows += priceRow(t('price.discount'), -price.discount, price.currency);
    if (price.provider_fee > 0) rows += priceRow(t('price.provider'), price.provider_fee, price.currency);
    rows += '<div class="price-row total"><span>' + esc(t('price.total')) + '</span><strong>' + esc(formatMoney(price.amount_due, price.currency)) + '</strong></div>';
  } else {
    rows += '<p class="muted">' + esc(t('price.onRequest')) + '</p>';
  }
  var official = price.official_fee_verified && price.official_fee > 0
    ? priceRow(t('price.official'), price.official_fee, price.currency)
    : '<p class="small muted">' + esc(t('price.officialUnverified')) + '</p>';
  var officialText = tf(service, 'official_fee_text');
  var cash = methods.filter(function (m) { return m.cash; });
  return '<div class="card stack price-box"><h2>' + icon('cash') + esc(t('price.title')) + '</h2>' + rows +
    '<div class="official-fee">' + official + (officialText ? '<p class="small">' + esc(officialText) + '</p>' : '') + '</div>' +
    '<p class="small muted">' + esc(t('price.separate')) + '</p>' +
    (methods.length ? '<h3>' + esc(t('price.methods')) + '</h3><ul class="pay-methods">' + methods.map(function (m) {
      return '<li class="pay-method"><div class="pm-head">' + icon(methodIcon(m)) + '<span class="pm-name"><strong>' + esc(tf(m, 'name')) + '</strong>' +
        (m.cash ? '<span class="badge success plain">' + esc(t('price.noBank')) + '</span>' : '') + '</span></div>' +
        '<div class="pm-body"><p class="small"><strong>' + esc(t('price.howItWorks')) + '</strong></p><ol class="pm-steps small">' +
          '<li>' + esc(t('price.step1')) + '</li><li>' + esc(tvP('price.step2', { method: tf(m, 'name') })) + '</li><li>' + esc(t('price.step3')) + '</li></ol>' +
          methodInstructions(m) +
          (tf(m, 'location') ? '<p class="small row">' + icon('mapPin') + esc(tf(m, 'location')) + '</p>' : '') +
          (tf(m, 'provider_fee_text') ? '<p class="small muted">' + esc(tf(m, 'provider_fee_text')) + '</p>' : '') +
        '</div></li>';
    }).join('') + '</ul>' : '') +
    (cash.length ? '<div class="notice success small">' + icon('cash') + '<span>' + esc(t('cash.text')) + '</span></div>' : '') +
    '</div>';
}

function tvP(key, vars) { return t(key).replace(/\{(\w+)\}/g, function (_, k) { return vars[k] == null ? '' : vars[k]; }); }

function priceRow(label, amount, currency) {
  return '<div class="price-row"><span>' + esc(label) + '</span><span>' + esc(formatMoney(amount, currency)) + '</span></div>';
}

function renderService(slug) {
  loadData('svc:' + slug, function () { return api('api_getService', slug); }, function (d) {
    var s = d.service, c = d.category;
    var byLang = {};
    d.content.forEach(function (x) { byLang[x.lang] = x; });
    var content = byLang[currentLang] || byLang[SUPPORTED_LANGS.filter(function (l) { return byLang[l]; })[0]] || null;
    var sections = content ? [['svc.about', content.description], ['svc.eligibility', content.eligibility], ['svc.procedure', content.procedure],
      ['svc.documents', content.required_documents], ['svc.notes', content.notes]].filter(function (x) { return x[1]; }) : [];
    var translated = !!content;
    var otherLangOnly = content && content.lang !== currentLang;
    setMain(pageSection(
      crumbs([{ label: t('nav.services'), href: '#/services' }].concat(c ? [{ label: tf(c, 'title'), href: '#/category/' + encodeURIComponent(c.slug) }] : []).concat([{ label: tf(s, 'title') }])) +
      '<div class="page-head"><span class="icon-badge lg">' + icon(c ? c.icon : 'file') + '</span><div><h1>' + esc(tf(s, 'title')) + '</h1>' +
      (tf(s, 'summary') ? '<p class="muted">' + esc(tf(s, 'summary')) + '</p>' : '') +
      (requestable(s) ? '<div class="head-cta">' + requestButton(s) + '</div>' : '') + '</div></div>' +
      '<div class="svc-layout"><div class="stack-lg">' +
        (sections.length ? sections.map(function (x) { return '<div class="card"><h2>' + esc(t(x[0])) + '</h2>' + textBlock(x[1]) + '</div>'; }).join('')
          : '<div class="notice">' + icon('info') + '<span>' + esc(t('svc.pending')) + '</span></div>') +
        (translated ? '<p class="small muted">' + esc(t('svc.translationNote')) + '</p>' : '') +
        (otherLangOnly ? '<p class="small muted">' + esc(t('svc.otherLangOnly')) + '</p>' : '') +
        (tf(s, 'institutions') ? '<div class="card"><h2>' + esc(t('svc.institutions')) + '</h2><p>' + esc(tf(s, 'institutions')) + '</p></div>' : '') +
        (s.official_links.length ? '<div class="card"><h2>' + esc(t('svc.links')) + '</h2><ul class="link-list">' + s.official_links.map(function (l) {
          return '<li><a href="' + esc(safeUrl(l.url)) + '" target="_blank" rel="noopener">' + icon('globe') + esc(l.label || l.url) + '</a></li>';
        }).join('') + '</ul></div>' : '') +
        (d.documents.length ? '<div><h2>' + esc(t('cat.docs')) + '</h2>' + docList(d.documents) + '</div>' : '') +
        (d.faqs.length ? '<div><h2>' + esc(t('cat.faq')) + '</h2>' + faqList(d.faqs) + '</div>' : '') +
        (s.verified_at ? '<p class="small muted">' + esc(tv('svc.verified', { date: String(s.verified_at).slice(0, 10) })) + '</p>' : '') +
      '</div><aside class="stack-lg svc-aside">' +
        priceBox(d.price, d.paymentMethods, s) +
        '<div class="notice small">' + icon('info') + '<span>' + esc(t('svc.notOfficial')) + '</span></div>' +
      '</aside></div>'));
  });
}

function toBoolC(v) { return v === true || v === 'TRUE' || v === 'true'; }

/** Requests are allowed unless an admin explicitly unticked "Assistance can be requested". */
function requestable(s) { return !(s.requestable === false || s.requestable === 'FALSE' || s.requestable === 'false'); }

function requestButton(s) {
  return '<a class="btn btn-accent btn-block" href="#/request/' + encodeURIComponent(s.slug) + '">' + icon('chat') + esc(t('svc.request')) + '</a>';
}

/* ---- Search -------------------------------------------------------------------------- */
function renderSearch(q) {
  loadData('search:' + q, function () { return api('api_search', q); }, function (d) {
    var none = !d.categories.length && !d.services.length;
    setMain(pageSection(crumbs([{ label: tv('search.title', { q: q }) }]) +
      '<form class="search" role="search" id="page-search">' + icon('search') +
      '<input class="input" id="q2" type="search" value="' + esc(q) + '" aria-label="' + esc(t('hero.search')) + '"></form>' +
      '<h1>' + esc(tv('search.title', { q: q })) + '</h1>' +
      (none ? '<p class="muted">' + esc(t('search.none')) + '</p>' : '') +
      (d.categories.length ? '<div><h2>' + esc(t('search.cats')) + '</h2><div class="svc-list">' + d.categories.map(function (c) {
        return '<a class="card card-sm interactive svc-item" href="#/category/' + encodeURIComponent(c.slug) + '"><span>' + esc(tf(c, 'title')) + '</span>' + icon('chevron', 'flip-rtl') + '</a>';
      }).join('') + '</div></div>' : '') +
      (d.services.length ? '<div><h2>' + esc(t('search.services')) + '</h2>' + serviceList(d.services) + '</div>' : '')));
    $('#page-search').addEventListener('submit', function (e) {
      e.preventDefault();
      var v = $('#q2').value.trim();
      if (v) navigate('#/search/' + encodeURIComponent(v), route);
    });
  });
}

/* ---- Static pages (About / Privacy / Terms) — editable as Homepage blocks ------------ */
function renderStatic(block) {
  loadData('home', function () { return api('api_getHome'); }, function (d) {
    var blocks = (d.blocks || []).filter(function (b) { return b.block === block; });
    var titleKey = { about: 'nav.about', privacy: 'footer.privacy', terms: 'footer.terms' }[block];
    var body = blocks.length ? blocks.map(function (b) { return textBlock(tf(b, 'value')); }).join('')
      : '<p>' + esc(block === 'about' ? t('page.aboutDefault') : t('page.legalPending')) + '</p>';
    setMain(pageSection(crumbs([{ label: t(titleKey) }]) + '<div class="card stack"><h1>' + esc(t(titleKey)) + '</h1>' + body +
      '<div class="notice small">' + icon('info') + '<span>' + esc(t('footer.disclaimer')) + '</span></div></div>'));
  });
}
